CREATE OR REPLACE FUNCTION public.merge_expense_vendor(p_tenant uuid,p_from uuid,p_into uuid) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE n integer; BEGIN IF p_from=p_into OR NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin approval required'; END IF; PERFORM id FROM public.suppliers WHERE tenant_id=p_tenant AND id IN(p_from,p_into) ORDER BY id FOR UPDATE; IF (SELECT count(*) FROM public.suppliers WHERE tenant_id=p_tenant AND id IN(p_from,p_into))<>2 THEN RAISE EXCEPTION 'Vendor not available'; END IF; IF EXISTS(SELECT 1 FROM public.expense_bills WHERE tenant_id=p_tenant AND supplier_id=p_from AND approval_status IN('posted','reversed')) THEN RAISE EXCEPTION 'Booked bills must retain their vendor; merge cannot change locked records'; END IF; UPDATE public.expense_bills SET supplier_id=p_into,supplier_account_id=NULL WHERE tenant_id=p_tenant AND supplier_id=p_from; GET DIAGNOSTICS n=ROW_COUNT; UPDATE public.expense_recurring_rules SET supplier_id=p_into WHERE tenant_id=p_tenant AND supplier_id=p_from; UPDATE public.expense_vendor_statements SET supplier_id=p_into WHERE tenant_id=p_tenant AND supplier_id=p_from AND approval_status NOT IN('posted','reversed'); INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(p_tenant,auth.uid(),'merge_expense_vendor','suppliers',p_from::text,jsonb_build_object('into',p_into,'bills_relinked',n)); RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.approve_staff_expense_claim(p_claim uuid,p_payout text) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE c public.staff_reimbursements%ROWTYPE; debit_account uuid; payable uuid; j uuid; BEGIN SELECT * INTO c FROM public.staff_reimbursements WHERE id=p_claim FOR UPDATE; IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),c.tenant_id) THEN RAISE EXCEPTION 'Claim not available'; END IF; IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager approval required'; END IF; IF c.amount>300 AND NOT public.people_owner(c.tenant_id,auth.uid()) THEN RAISE EXCEPTION 'Owner approval required over HK$300'; END IF; IF p_payout NOT IN('bank','payroll','petty_cash') THEN RAISE EXCEPTION 'Choose a payment method'; END IF; IF c.approval_status='approved' THEN RETURN c.journal_entry_id; END IF; IF c.status='paid' THEN RAISE EXCEPTION 'Claim already paid'; END IF; SELECT gl_account_id INTO debit_account FROM public.petty_cash_classifications WHERE id=c.category_id AND tenant_id=c.tenant_id; IF debit_account IS NULL THEN RAISE EXCEPTION 'Pick an account for this category'; END IF; SELECT id INTO payable FROM public.chart_of_accounts WHERE tenant_id=c.tenant_id AND name='Staff Reimbursements Payable' ORDER BY code LIMIT 1; IF payable IS NULL THEN RAISE EXCEPTION 'Staff Reimbursements Payable account is missing'; END IF; INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,status,posted_at,created_by) VALUES(c.tenant_id,c.claim_date,'Staff reimbursement — '||c.claimant_name||' — '||c.description,'staff_reimbursement',c.id,'posted',now(),auth.uid()) RETURNING id INTO j; INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,line_no,memo) VALUES(c.tenant_id,j,debit_account,c.amount,0,1,c.description),(c.tenant_id,j,payable,0,c.amount,2,'Owed to '||c.claimant_name); UPDATE public.staff_reimbursements SET approval_status='approved',approved_by=auth.uid(),approved_at=now(),journal_entry_id=j,payout_method=p_payout WHERE id=c.id; INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(c.tenant_id,auth.uid(),'approve_staff_claim','staff_reimbursements',c.id::text,jsonb_build_object('journal_entry_id',j,'amount',c.amount,'payout',p_payout)); RETURN j; END $$;